import fs from 'node:fs/promises';
import path from 'node:path';
import { z } from 'zod';
import { siteSchema } from '../config/schema.ts';
import { RESERVED_ROOT_SLUGS } from '../content/slug.ts';
import { runIfMain } from '../lib/cli.ts';
import { DOCS, SITE_SAMPLE } from '../lib/paths.ts';

type Schema = z.core.JSONSchema.JSONSchema;

/** The generated files. */
export const SCHEMA_FILE = path.join(SITE_SAMPLE, 'site.schema.json');
export const REFERENCE_FILE = path.join(DOCS, 'site-yaml.md');

export interface Row {
  readonly path: string;
  readonly type: string;
  readonly required: boolean;
  readonly description: string;
}

const asSchema = (s: z.core.JSONSchema._JSONSchema | undefined): Schema =>
  typeof s === 'object' ? s : {};

const code = (text: string): string => `\`${text}\``;

/** The alternatives of a position: a `oneOf` or `anyOf` is flattened, anything else stands for itself. */
const variantsOf = (schemas: readonly Schema[]): Schema[] =>
  schemas.flatMap((s) => s.oneOf ?? s.anyOf ?? [s]);

/** The type of a value as a short Markdown phrase. */
function typeOf(schema: Schema): string {
  const alternatives = schema.oneOf ?? schema.anyOf;
  if (alternatives) {
    return [...new Set(alternatives.map(typeOf))].join(' \\| ');
  }
  if (schema.const !== undefined) {
    return code(JSON.stringify(schema.const));
  }
  if (schema.enum) {
    return schema.enum.map((v) => code(String(v))).join(' \\| ');
  }
  if (schema.prefixItems) {
    return `[${schema.prefixItems.map((s) => typeOf(asSchema(s))).join(', ')}]`;
  }
  switch (schema.type) {
    case 'array':
      return `list of ${typeOf(Array.isArray(schema.items) ? {} : asSchema(schema.items))}`;
    case 'integer':
      return `integer ≥ ${schema.minimum ?? 0}`;
    case 'object':
      return 'mapping';
    default:
      return String(schema.type);
  }
}

/** Rows for the members of the alternatives `variants`, with `prefix` before each name. */
function memberRows(prefix: string, variants: readonly Schema[]): Row[] {
  const names = new Set(variants.flatMap((v) => Object.keys(v.properties ?? {})));
  return [...names].flatMap((name) => {
    const schemas = variants.flatMap((v) =>
      v.properties && Object.hasOwn(v.properties, name) ? [asSchema(v.properties[name])] : [],
    );
    const at = `${prefix}${name}`;
    return [
      {
        path: at,
        type: [...new Set(schemas.map(typeOf))].join(' \\| '),
        required: variants.every((v) => v.required?.includes(name) === true),
        description: schemas.find((s) => s.description)?.description ?? '',
      },
      ...nestedRows(at, schemas),
    ];
  });
}

/** Rows below the position `at`: its own members, the members of its mapping values and of its list items. */
function nestedRows(at: string, schemas: readonly Schema[]): Row[] {
  const variants = variantsOf(schemas);
  const values = variants.flatMap((v) =>
    typeof v.additionalProperties === 'object' ? [v.additionalProperties] : [],
  );
  const items = variants.flatMap((v) =>
    typeof v.items === 'object' && !Array.isArray(v.items) ? [v.items] : [],
  );
  const dotted = at && `${at}.`;
  return [
    ...memberRows(dotted, variants),
    ...memberRows(`${dotted}<key>.`, variantsOf(values)),
    ...memberRows(`${at}[].`, variantsOf(items)),
  ];
}

const cell = (text: string): string => text.replaceAll('|', '\\|');

/** `site.schema.json`: the JSON Schema of `site.yaml`, for editors with YAML language support. */
export function schemaJson(): string {
  return `${JSON.stringify(z.toJSONSchema(siteSchema, { io: 'input' }), null, 2)}\n`;
}

/** One row per `site.yaml` key, nested keys after their parent. */
export const referenceRows = (): Row[] =>
  nestedRows('', [z.toJSONSchema(siteSchema, { io: 'input' })]);

/** `docs/site-yaml.md`: the reference of every `site.yaml` key. */
export function referenceMarkdown(): string {
  const rows = referenceRows().map(
    (r) =>
      `| ${code(r.path)} | ${r.type} | ${r.required ? 'yes' : 'no'} | ${cell(r.description)} |`,
  );
  return `<!-- Generated by \`make docs\` from src/config/schema.ts. Do not edit. -->

# site.yaml reference

\`site.yaml\` sits at the top of the site directory. Unknown keys are errors at every level. A
commented starting point is \`site.sample/site.yaml.sample\`; \`make init-site\` copies it, together
with \`site.schema.json\` that gives editors with YAML language support completion and checks.

| Key | Type | Required | Description |
| --- | --- | --- | --- |
${rows.join('\n')}

## Rules beyond the table

- A section key is a clean slug: lowercase letters, digits and single hyphens. It must contain a
  letter and must not be one of ${[...RESERVED_ROOT_SLUGS].map(code).join(', ')}.
- \`menu: taxonomy\` needs at least one entry in \`taxonomies\`.
- A \`latest\` or \`featured\` block names a declared section.
- Every \`menu\` entry is a declared section or a top-level page of the site directory; none repeats.
- \`favicon\` and \`appleTouchIcon\` are relative paths with \`/\` separators to files below the site
  directory, without \`..\` segments and without a segment starting with \`_\`.
- \`baseUrl\` is an origin only: scheme, host and optional port, no path and no trailing slash.
`;
}

/** Writes both generated files. */
export async function main(
  schemaFile = SCHEMA_FILE,
  referenceFile = REFERENCE_FILE,
): Promise<void> {
  await fs.writeFile(schemaFile, schemaJson());
  await fs.writeFile(referenceFile, referenceMarkdown());
}

await runIfMain(import.meta.url, async () => {
  await main();
  return 0;
});
